import{_ as a,c as o,o as i,a3 as s}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"Opciones de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy-choices.md","filePath":"es/guide/privacy-choices.md","lastUpdated":1786595765000}'),n={name:"es/guide/privacy-choices.md"};function r(t,e,c,d,l,p){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="opciones-de-privacidad" tabindex="-1">Opciones de privacidad <a class="header-anchor" href="#opciones-de-privacidad" aria-label="Permalink to &quot;Opciones de privacidad&quot;">​</a></h1><p>ClipboardxAI es una aplicación local-primero. Dado que sus datos permanecen en su dispositivo, no recopilamos, vendemos ni compartimos ninguna información personal.</p><h2 id="datos-que-conservamos-localmente" tabindex="-1">Datos que conservamos localmente <a class="header-anchor" href="#datos-que-conservamos-localmente" aria-label="Permalink to &quot;Datos que conservamos localmente&quot;">​</a></h2><p>ClipboardxAI almacena todos los datos localmente en su Mac:</p><ul><li>Historial del portapapeles y preferencias de la aplicación</li><li>Acciones personalizadas y configuración</li><li>API keys (en el Keychain, solo si configura un proveedor en la nube)</li><li>Registros de depuración (si están activados)</li></ul><p>Ninguno de estos datos es subido a ningún servidor por la propia aplicación.</p><h2 id="opcion-de-ia-en-la-nube" tabindex="-1">Opción de IA en la nube <a class="header-anchor" href="#opcion-de-ia-en-la-nube" aria-label="Permalink to &quot;Opción de IA en la nube&quot;">​</a></h2><p>Las funciones de IA en la nube están <strong>desactivadas por defecto</strong>. Envían el contenido solo al proveedor que elija, usando su propia API key, y solo cuando usted activa una acción en la nube. Puede revisar o eliminar los proveedores configurados en <strong>Ajustes → IA</strong>.</p><h2 id="sus-derechos" tabindex="-1">Sus derechos <a class="header-anchor" href="#sus-derechos" aria-label="Permalink to &quot;Sus derechos&quot;">​</a></h2><p>Dado que ClipboardxAI no recopila ni almacena datos personales en nuestros servidores, no hay datos personales a los que podamos acceder, eliminar o transferir. Todos sus datos se pueden gestionar directamente dentro de la aplicación o eliminando la carpeta del contenedor de la aplicación:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><h2 id="no-venta" tabindex="-1">No venta <a class="header-anchor" href="#no-venta" aria-label="Permalink to &quot;No venta&quot;">​</a></h2><p>ClipboardxAI no vende ninguna información personal. No usamos servicios de analítica, publicidad o seguimiento de terceros de ningún tipo.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h2><p>Si tiene preguntas sobre las opciones de privacidad, abra un issue en: <code>https://github.com/clipboardxAI/clipboard-site/issues</code></p>',15)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
